package com.javaintroduction;

public class WrapperClasses {
	Integer StudentId=1;
	String StudentName="Sindhuja";
	Integer age=21;
	Double Marks=88D;
	Character Grade='A';
	Boolean Passed=true;
	
	

	public static void main(String[] args) {
		WrapperClasses w1= new WrapperClasses();
		System.out.println(w1.StudentId);
		System.out.println(w1.StudentName);
		System.out.println(w1.age);
		System.out.println(w1.Marks);
		System.out.println(w1.Grade);
		System.out.println(w1.Passed);
		// TODO Auto-generated method stub

	}

}
